function [ dx ] = modelo_eq( t_out, x, ws, ks,ts,reg,ns,ne,te,n_s,n_c,ns_a,ts_frozen,points,tal,est,yi,utarg,tstarg,nstarg)
[u] = ver_reg_est1(ws,yi,t_out);
[uref] = ver_reg_est1(ws,yi,t_out);
;

y(1)=((u(1) +u(2)+6));

dx(1)=(6 - y(1)*x(1) - 17.6*x(1)*x(2) - 23*x(1)*x(6)*u(3)                                        )*tal;
dx(2)=(u(1) - y(1)*x(2) - 17.6*x(1)*x(2) - 146*x(2)*x(3)                                         )*tal;
dx(3)=(u(2) - y(1)*x(3)-73*x(2)*x(3)                                                             )*tal;
dx(4)=(-y(1)*x(4)+35.2*x(1)*x(2)-51.3*x(4)*x(5)                                                  )*tal;
dx(5)=(-y(1)*x(5)+219*x(2)*x(3)-51.3*x(4)*x(5)                                                   )*tal;
dx(6)=(-y(1)*x(6)+102.6*x(4)*x(5)-23*x(1)*x(6)*u(3)                                              )*tal;
dx(7)=(-y(1)*x(7)+46*x(1)*x(6)*u(3)                                                              )*tal;
dx(8)=(5.8*(y(1)*x(1)-6)-3.7*u(1)-4.1*u(2)+y(1)*(23*x(4)+11*x(5)+28*x(6)+35*x(7))-5*u(3)^2 -0.099)*tal;
dx=transp(dx);
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
